from pathlib import Path
import json,hashlib
from html import escape
P=Path(__file__).resolve().parents[1]
R=P.parent
v=json.loads((P/'audits/validation_checkpoint_dx5.json').read_text())
rows=[]
for f in v['fichiers']:
 p=P/f['fichier']
 assert hashlib.sha256(p.read_bytes()).hexdigest()==f['sha256']
 assert p.stat().st_size==f['octets']
 x,y=f['texte_fiche_octets'],f['texte_fenetres_octets']
 limite=100000 if 'Phase_A' in p.name else 9000
 rows.append('<tr><th scope="row"><a href="LOT_037/'+escape(p.name)+'">'+escape(p.name.replace('LOT_037_','').replace('_V0','').replace('.html',''))+'</a></th>'+''.join('<td>'+t+'</td>' for t in [f'{x/1000:.3f}',f'{y/1000:.3f}',f'{(x+y)/1000:.3f}',f'{f["octets"]/1000:.3f}',str(limite//1000),'Oui' if x<=limite else 'Non','Oui' if 80000<=f['octets']<=150000 else 'Non',str(f['citations_aips'])])+'</tr>')
page='''<!doctype html><html lang="fr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>LOT037 — bilan du checkpoint</title><style>body{font:17px/1.6 system-ui,sans-serif;color:#173044;background:#f4f6f7;margin:0}main{max-width:1200px;margin:auto;padding:2rem}h1,h2{line-height:1.2}article{background:white;padding:1.5rem;border-radius:12px;margin:1rem 0}table{border-collapse:collapse;width:100%;font-size:.85rem}th,td{text-align:right;border-bottom:1px solid #ccd7dc;padding:.7rem}th:first-child{text-align:left}thead{background:#e5eff2}a{color:#075e8a}.table{overflow-x:auto}.statut{border-left:6px solid #be8418}small{color:#405866}</style></head><body><main><h1>LOT037 : six leçons produites sur onze</h1><p>Checkpoint du 31 octobre 2026 · Phase A et DX1–5 · Le lot reste incomplet.</p><article class="statut"><h2>État réel</h2><p>84 questions, 150 conditions statiques V8 satisfaites, 98 paragraphes AIPS retrouvés dans les notices originales. Cinq nouvelles monographies rédigées et relues dans la session principale. Le prochain diagnostic est DX6, Infection cervicale profonde.</p><p>Dernier lot entièrement produit : LOT036, commit b7acb939. Ce bilan concerne uniquement le checkpoint du LOT037. Le rapport général ETAT_DES_LIEUX.html reste un instantané antérieur.</p></article><article><h2>Tailles exactes</h2><p>1 Ko = 1000 octets. <strong>x</strong> mesure le texte de la fiche sans fenêtres ; <strong>y</strong> mesure le texte des fenêtres et dépliants. <strong>x+y</strong> représente leur somme, pas le poids du HTML. Le HTML contient aussi balisage, styles et polices embarquées.</p><div class="table"><table><thead><tr><th>Leçon</th><th>x Ko</th><th>y Ko</th><th>x+y Ko</th><th>HTML Ko</th><th>Limite x Ko</th><th>Taille V8 respectée</th><th>Bande historique HTML 80–150 Ko</th><th>Citations AIPS</th></tr></thead><tbody>'''+''.join(rows)+'''</tbody></table></div><p>Référence : PROMPT_CODEX.md §8, fiche x ≤9 Ko pour un diagnostic, x ≤100 Ko pour toute leçon. Le texte détaillé reste dans les fenêtres. La bande historique de poids HTML est présentée séparément ; elle ne remplace pas la limite de texte V8.</p></article><article><h2>Conformité et limites</h2><ul><li>14 parties et 14 questions par leçon : vérifiées sur les six fichiers.</li><li>Relecture médicale et linguistique : interne, tracée, avec corrections réelles. Aucun audit indépendant ni validation clinique humaine.</li><li>AIPS : contrôle des citations exactes ; cela ne certifie pas à lui seul l’indication, le choix thérapeutique ou l’exhaustivité médicale.</li><li>Audit linguistique historique : négatif, avec notamment title et h3 incompatibles avec les règles V8 appliquées. Les rapports bruts sont conservés, y compris les avertissements de phrases longues dans les verbatim.</li><li>Structure V8 : contrôles statiques complémentaires positifs. Aucun test de rendu navigateur.</li><li>Le classement de fréquence suisse n’est pas démontré. Les prophylaxies spécialisées et certaines alternatives antibiotiques restent hors d’un protocole exhaustif.</li><li>Conformité globale au prompt : non certifiée. DX6–10 sont absents ; la relecture transversale complète du lot reste à faire.</li></ul><p><a href="LOT_037/audits/validation_checkpoint_dx5.json">Mesures et contrôles statiques</a> · <a href="LOT_037/audits/controle_harnais_checkpoint_dx5.json">Harnais officiel brut</a> · <a href="LOT_037/audits/RELECTURE_DX1_3.md">Relecture DX1–3</a> · <a href="LOT_037/audits/RELECTURE_DX4_5.md">Relecture DX4–5</a> · <a href="LOT_037/HELP.md">Points ouverts</a></p></article><small>Les veilles locales contrôlent le contrat toutes les60secondes pendant la vie de l’environnement. Elles ne rédigent pas les leçons.</small></main></body></html>'''
dest=R/'BILAN_CHECKPOINT_LOT_037.html';dest.write_text(page)
print(dest)
